import { expect, it } from 'vitest';
import { PREFERENCES_KEY, readPreferences, savePreferences } from './storage.ts';
import type { PreferenceStorage } from './storage.ts';

it('validates saved sizes and integer capped best scores as unknown input', () => {
  const storage = { getItem: () => JSON.stringify({ version: 1, size: 16,
    bests: { 4: 8, 6: -1, 8: 3.5, 10: 1000000, 12: '5', 14: 999999, 16: 128 } }), setItem: () => {} };
  expect(readPreferences(storage)).toEqual({ size: 16, bests: { 4: 8, 14: 999999, 16: 128 } });
  expect(readPreferences({ ...storage, getItem: () => '{' })).toEqual({ size: 4, bests: {} });
  expect(readPreferences({ ...storage, getItem: () => '{"version":1,"size":5}' })).toEqual({ size: 4, bests: {} });
});
it('catches unavailable storage and writes only its own key', () => {
  const unavailable: PreferenceStorage = { getItem: () => { throw new Error('blocked'); }, setItem: () => { throw new Error('blocked'); } };
  expect(readPreferences(unavailable)).toEqual({ size: 4, bests: {} });
  expect(() => savePreferences(unavailable, { size: 4, bests: {} })).not.toThrow();
  const keys: string[] = [];
  savePreferences({ getItem: () => null, setItem: (key) => { keys.push(key); } }, { size: 6, bests: { 6: 18 } });
  expect(keys).toEqual([PREFERENCES_KEY]);
});
import { expect, it } from 'vitest';
import { describeFace } from './face.ts';

it('identifies all 128 faces by shape, marker and fill without color', () => {
  const names = Array.from({ length: 128 }, (_, id) => describeFace(id).name);
  expect(new Set(names.map((name) => name.slice(name.indexOf(' ') + 1))).size).toBe(128);
  expect(names[0]).toBe('cyan solid circle, marker top');
  expect(names[64]).toBe('cyan outline circle, marker top');
  expect(names[127]).toBe('ice outline chevron, marker top-left');
});
it('places every marker 40 units from center, including square diagonals', () => {
  for (let id = 0; id < 128; id += 1) {
    const face = describeFace(id);
    expect(Math.hypot(face.x - 50, face.y - 50)).toBeCloseTo(40, 10);
  }
  expect(describeFace(9)).toMatchObject({ shape: 'square', x: 50 + 40 / Math.sqrt(2), y: 50 - 40 / Math.sqrt(2) });
});
import { expect, it } from 'vitest';
import { focusDestination } from './navigation.ts';

it('moves in row order without wrapping at each edge', () => {
  expect(focusDestination(0, 4, 'ArrowLeft')).toBe(0);
  expect(focusDestination(0, 4, 'ArrowUp')).toBe(0);
  expect(focusDestination(3, 4, 'ArrowRight')).toBe(3);
  expect(focusDestination(15, 4, 'ArrowDown')).toBe(15);
  expect(focusDestination(5, 4, 'ArrowLeft')).toBe(4);
  expect(focusDestination(5, 4, 'ArrowRight')).toBe(6);
  expect(focusDestination(5, 4, 'ArrowUp')).toBe(1);
  expect(focusDestination(5, 4, 'ArrowDown')).toBe(9);
  expect(focusDestination(0, 4, 'Tab')).toBeNull();
});

