import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { createGame } from '../src/game/state.ts';
import type { GameState } from '../src/game/state.ts';
import { decodeSnapshot, encodeSnapshot } from '../src/game/snapshot.ts';

export const cards = (page: Page) => page.getByRole('group', { name: 'Card board' }).getByRole('button');
export async function tools(page: Page) {
  const details = page.locator('details');
  if (!(await details.getAttribute('open') !== null)) await page.getByText('Reproduce a game', { exact: true }).click();
}
export async function loadBoard(page: Page, code = 'np1-4-1') {
  await tools(page);
  await page.getByLabel('Board code', { exact: true }).fill(code);
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue(code.trim());
}
export async function readSnapshot(page: Page): Promise<GameState> {
  await tools(page);
  await page.getByRole('button', { name: 'Export snapshot' }).click();
  const game = decodeSnapshot(await page.getByLabel('Snapshot JSON').inputValue());
  if (!game) throw new Error('Exported invalid snapshot');
  return game;
}
export async function loadSnapshot(page: Page, state: GameState) {
  await tools(page);
  await page.getByLabel('Snapshot JSON').fill(encodeSnapshot(state));
  await page.getByRole('button', { name: 'Load snapshot' }).click();
}
export function game(code = 'np1-4-1'): GameState {
  const state = createGame(code);
  if (!state) throw new Error('Invalid test board');
  return state;
}
export function pairs(state: GameState): readonly number[][] {
  const result = new Map<number, number[]>();
  state.board.deck.forEach((face, index) => result.set(face, [...(result.get(face) ?? []), index]));
  return [...result.values()];
}
export function nearWin(moves = 7): GameState {
  return { ...game(), matched: Array.from({ length: 16 }, (_, index) => index).filter((index) => index !== 12 && index !== 13),
    selection: { kind: 'closed' }, started: true, moves, elapsedMs: 1500 };
}
export async function frozen(page: Page) {
  const time = new Date('2026-11-04T12:00:00Z');
  await page.clock.install({ time });
  await page.clock.pauseAt(time);
  await page.goto('/');
}
export async function visibility(page: Page, hidden: boolean) {
  await page.evaluate((value) => {
    Object.defineProperty(document, 'hidden', { configurable: true, value });
    document.dispatchEvent(new Event('visibilitychange'));
  }, hidden);
}
import { expect, test } from '@playwright/test';
import { SIZES } from '../src/game/boardCode.ts';
import { cards, frozen, game, loadBoard, pairs, readSnapshot, visibility } from './gameDriver.ts';

for (const size of SIZES) test(`finishes a complete ${size}x${size} deal`, async ({ page }) => {
  await page.goto('/');
  await loadBoard(page, `np1-${size}-1`);
  const state = game(`np1-${size}-1`);
  for (const indices of pairs(state)) for (const index of indices) await cards(page).nth(index).click();
  await expect(page.getByRole('heading', { name: 'All pairs found!' })).toBeVisible();
  await expect(page.getByText(`Moves: ${size * size / 2}`, { exact: true })).toBeVisible();
  await expect(page.getByText(`Pairs: ${size * size / 2}/${size * size / 2}`, { exact: true })).toBeVisible();
  await expect(page.locator('.card.matched')).toHaveCount(size * size);
  await expect(page.getByText(`Best: ${size * size / 2}`, { exact: true })).toBeVisible();
});

test('one reveal, repeats, matches and the exact active mismatch interval', async ({ page }) => {
  await frozen(page);
  await loadBoard(page);
  await cards(page).nth(0).click();
  await cards(page).nth(0).click();
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await cards(page).nth(11).click();
  await cards(page).nth(0).press('Enter');
  await expect(page.getByText('Pairs: 1/8', { exact: true })).toBeVisible();
  await cards(page).nth(1).click();
  await cards(page).nth(2).click();
  await cards(page).nth(3).press('Enter');
  await page.clock.runFor(799);
  expect((await readSnapshot(page)).selection).toEqual({ kind: 'mismatch', first: 1, second: 2, remainingMs: 1 });
  await page.clock.runFor(1);
  expect((await readSnapshot(page)).selection).toEqual({ kind: 'closed' });
  await expect(page.getByText('Moves: 2', { exact: true })).toBeVisible();
});

