export const SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Size = (typeof SIZES)[number];
export const MAX_SEED = 2147483646;
const MODULUS = 2147483647;

export interface BoardDescription {
  readonly code: string;
  readonly size: Size;
  readonly seed: number;
}

export function isSize(value: unknown): value is Size {
  return SIZES.some((size) => size === value);
}

export function parseBoardCode(text: string): BoardDescription | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(text);
  if (!match || match[0] !== text) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code: text, size, seed });
}

export function nextRandom(state: number): number {
  // The largest product is below 2^53, so every multiplication is exact.
  return (state * 16807) % MODULUS;
}

export function drawBounded(state: number, bound: number): readonly [number, number] {
  const limit = Math.floor(MAX_SEED / bound) * bound;
  let next = state;
  do {
    next = nextRandom(next);
  } while (next - 1 >= limit);
  return [next, (next - 1) % bound];
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, index) => Math.floor(index / 2));
  let random = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const [next, target] = drawBounded(random, index + 1);
    random = next;
    const first = deck[index];
    const second = deck[target];
    if (first === undefined || second === undefined) throw new Error('Invalid shuffle position');
    deck[index] = second;
    deck[target] = first;
  }
  return Object.freeze(deck);
}
import { generateDeck, parseBoardCode } from './boardCode.ts';
import type { BoardDescription } from './boardCode.ts';

export const SELECTION = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | { readonly kind: typeof SELECTION.closed }
  | { readonly kind: typeof SELECTION.one; readonly index: number }
  | { readonly kind: typeof SELECTION.mismatch; readonly first: number; readonly second: number; readonly remainingMs: number };

export interface GameState {
  readonly board: BoardDescription & { readonly deck: readonly number[] };
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return {
    board: Object.freeze({ ...board, deck: generateDeck(board) }),
    matched: [],
    selection: { kind: SELECTION.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}
import { isWon, SELECTION } from './state.ts';
import type { GameState } from './state.ts';

export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;
export const MISMATCH_MS = 800;

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isSafeInteger(index) || index < 0 || index >= state.board.deck.length ||
      state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case SELECTION.closed:
      return { ...state, selection: { kind: SELECTION.one, index }, started: true };
    case SELECTION.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[first] === state.board.deck[index]) {
        return { ...state, moves, matched: [...state.matched, first, index], selection: { kind: SELECTION.closed } };
      }
      return { ...state, moves, selection: { kind: SELECTION.mismatch, first, second: index, remainingMs: MISMATCH_MS } };
    }
    case SELECTION.mismatch:
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!state.started || isWon(state) || !Number.isFinite(milliseconds) || milliseconds <= 0) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  switch (state.selection.kind) {
    case SELECTION.closed:
    case SELECTION.one:
      return elapsedMs === state.elapsedMs ? state : { ...state, elapsedMs };
    case SELECTION.mismatch: {
      const remainingMs = state.selection.remainingMs - milliseconds;
      const selection = remainingMs <= 0
        ? { kind: SELECTION.closed }
        : { ...state.selection, remainingMs };
      return { ...state, elapsedMs, selection };
    }
  }
}
import { createGame } from './state.ts';
import type { GameState } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import { exactKeys, isIndex, isNonnegativeInteger, isObject, parseLimitedJson } from './validation.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTE_LIMIT = 1048576;
export const MAX_REPLAY_ACTIONS = 10000;

export function replayGame(text: string): GameState | null {
  const value = parseLimitedJson(text, REPLAY_BYTE_LIMIT);
  if (!isObject(value) || !exactKeys(value, ['version', 'boardCode', 'actions', 'endMs']) ||
      value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string' ||
      !isNonnegativeInteger(value.endMs) || !Array.isArray(value.actions) || value.actions.length > MAX_REPLAY_ACTIONS) return null;
  let state = createGame(value.boardCode);
  if (!state) return null;
  let time = 0;
  const actions: readonly unknown[] = value.actions;
  for (const action of actions) {
    if (!isObject(action) || !exactKeys(action, ['atMs', 'index']) ||
        !isNonnegativeInteger(action.atMs) || action.atMs < time || action.atMs > value.endMs ||
        !isIndex(action.index, state.board.deck.length)) return null;
    state = advanceGame(state, action.atMs - time);
    state = activateCard(state, action.index);
    time = action.atMs;
  }
  return advanceGame(state, value.endMs - time);
}

