export function focusDestination(index: number, size: number, key: string): number | null {
  const row = Math.floor(index / size);
  const column = index % size;
  switch (key) {
    case 'ArrowLeft': return column > 0 ? index - 1 : index;
    case 'ArrowRight': return column < size - 1 ? index + 1 : index;
    case 'ArrowUp': return row > 0 ? index - size : index;
    case 'ArrowDown': return row < size - 1 ? index + size : index;
    default: return null;
  }
}

export const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
export type Shape = (typeof SHAPES)[number];
export const POSITIONS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
export const PALETTE = [
  { name: 'cyan', color: '#63E7FF' }, { name: 'magenta', color: '#FF71D6' },
  { name: 'green', color: '#8BEA7D' }, { name: 'yellow', color: '#FFE082' },
  { name: 'orange', color: '#FFB064' }, { name: 'violet', color: '#B49AFF' },
  { name: 'rose', color: '#FF8296' }, { name: 'ice', color: '#D9F3FF' },
] as const;
const DIAGONAL = 40 / Math.sqrt(2);
const OFFSETS = [[0, -40], [DIAGONAL, -DIAGONAL], [40, 0], [DIAGONAL, DIAGONAL],
  [0, 40], [-DIAGONAL, DIAGONAL], [-40, 0], [-DIAGONAL, -DIAGONAL]] as const;

export function describeFace(id: number) {
  if (!Number.isInteger(id) || id < 0 || id > 127) throw new Error('Invalid face');
  const shape = SHAPES[id % 8];
  const marker = Math.floor(id / 8) % 8;
  const palette = PALETTE[marker];
  const position = POSITIONS[marker];
  const offset = OFFSETS[marker];
  if (!shape || !palette || !position || !offset) throw new Error('Invalid face parts');
  const fill = Math.floor(id / 64) === 0 ? 'solid' : 'outline';
  return { shape, color: palette.color, fill, x: 50 + offset[0], y: 50 + offset[1],
    name: `${palette.name} ${fill} ${shape}, marker ${position}` };
}
import { describeFace } from './face.ts';
import { FaceShape } from './FaceShape.tsx';

export function Face({ id }: { readonly id: number }) {
  const face = describeFace(id);
  return <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false">
    <g fill={face.fill === 'solid' ? face.color : 'none'} stroke={face.fill === 'outline' ? face.color : 'none'} strokeWidth="5" strokeLinejoin="round">
      <FaceShape shape={face.shape} />
    </g>
    <circle cx={face.x} cy={face.y} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
  </svg>;
}
import type { Shape } from './face.ts';

export function FaceShape({ shape }: { readonly shape: Shape }) {
  switch (shape) {
    case 'circle': return <circle cx="50" cy="50" r="25" />;
    case 'square': return <rect x="25" y="25" width="50" height="50" />;
    case 'triangle': return <path d="M50 25 75 75 25 75Z" />;
    case 'diamond': return <path d="M50 25 75 50 50 75 25 50Z" />;
    case 'star': return <path d="m50 25 7.3 16.8 17.7 1.3-13.6 11.5 4.1 17.4L50 62.8 34.5 72l4.1-17.4L25 43.1l17.7-1.3Z" />;
    case 'hexagon': return <path d="M37.5 25 62.5 25 75 50 62.5 75 37.5 75 25 50Z" />;
    case 'plus': return <path d="M42 25H58V42H75V58H58V75H42V58H25V42H42Z" />;
    case 'chevron': return <path d="M25 25H47L75 50 47 75H25L53 50Z" />;
  }
}
import { useCallback, useEffect, useRef } from 'react';

export function useActiveClock(generation: number, advance: (milliseconds: number) => void) {
  const previous = useRef(performance.now());
  const visible = useRef(!document.hidden);
  const epoch = useRef(0);
  const flush = useCallback(() => {
    const now = performance.now();
    const delta = Math.max(0, now - previous.current);
    previous.current = now;
    if (visible.current) advance(delta);
  }, [advance]);
  const reset = useCallback(() => {
    epoch.current += 1;
    previous.current = performance.now();
    visible.current = !document.hidden;
  }, []);

  useEffect(() => {
    let active = true;
    const token = epoch.current;
    let frame = 0;
    const render = () => {
      if (!active || token !== epoch.current) return;
      flush();
      frame = requestAnimationFrame(render);
    };
    const visibility = () => {
      if (!active || token !== epoch.current) return;
      flush();
      visible.current = !document.hidden;
    };
    frame = requestAnimationFrame(render);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      active = false;
      cancelAnimationFrame(frame);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [generation, flush]);
  return { flush, reset };
}

